const setRecordingStats = `-- name: SetRecordingStats :exec
UPDATE recordings SET drops = $1, errors = $2, scrambled = $3,
  state = CASE WHEN state IN ('completed', 'completed_with_errors')
    THEN CASE WHEN $1::bigint > 0 THEN 'completed_with_errors' ELSE 'completed' END
    ELSE state END,
  updated_at = $4
WHERE id = $5
`

type SetRecordingStatsParams struct {
	Drops     int64
	Errors    int64
	Scrambled int64
	Now       time.Time
	ID        uuid.UUID
}

// 録画を終えた後に解析したドロップ、エラー、スクランブルで、録画の集計を置き換える。
// 完了した録画は、ドロップの有無で、完了とエラーありの完了を決め直す。
func (q *Queries) SetRecordingStats(ctx context.Context, arg SetRecordingStatsParams) error {
	_, err := q.db.Exec(ctx, setRecordingStats,
		arg.Drops,
		arg.Errors,
		arg.Scrambled,
		arg.Now,
		arg.ID,
	)
	return err
}

const startRecording = `-- name: StartRecording :one
INSERT INTO recordings (id, reservation_id, service_id, event_id, name, description, start_at, end_at, state, failure_reason,
  protected, drops, errors, scrambled, audios, recorded_from, recorded_until, created_at, updated_at)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8, 'recording', NULL,
  false, 0, 0, 0,
  COALESCE((SELECT p.audios FROM programs p WHERE p.service_id = $3 AND p.event_id = $4), '[]'::jsonb),
  $9, NULL, $9, $9)
ON CONFLICT (reservation_id) DO UPDATE SET state = 'recording', failure_reason = NULL, recorded_until = NULL, updated_at = EXCLUDED.updated_at
RETURNING recordings.id, recordings.reservation_id, recordings.service_id, recordings.event_id, recordings.name, recordings.description, recordings.start_at, recordings.end_at, recordings.state, recordings.failure_reason, recordings.protected, recordings.drops, recordings.errors, recordings.scrambled, recordings.gaps, recordings.audios, recordings.program_lost, recordings.broadcast_started_at, recordings.broadcast_ended_at, recordings.not_broadcast, recordings.aired_event_id, recordings.recorded_from, recordings.recorded_until, recordings.created_at, recordings.updated_at, (xmax = 0)::boolean AS inserted
`

type StartRecordingParams struct {
	ID            uuid.UUID
	ReservationID *uuid.UUID
	ServiceID     int64
	EventID       *int64
	Name          string
	Description   string
	StartAt       time.Time
	EndAt         time.Time
	Now           time.Time
}

type StartRecordingRow struct {
	Recording Recording
	Inserted  bool
}

// 予約の録画を始める。引き継ぎや再開で、すでに録画があれば、それを続ける。新しく始めたかどうかを inserted で返す。
// 番組の音声の構成は、始めたときの番組から写す。続けるときは、最初に写したものを残す。
func (q *Queries) StartRecording(ctx context.Context, arg StartRecordingParams) (StartRecordingRow, error) {
	row := q.db.QueryRow(ctx, startRecording,
		arg.ID,
		arg.ReservationID,
		arg.ServiceID,
		arg.EventID,
		arg.Name,
		arg.Description,
		arg.StartAt,
		arg.EndAt,
		arg.Now,
	)
	var i StartRecordingRow
	err := row.Scan(
		&i.Recording.ID,
		&i.Recording.ReservationID,
		&i.Recording.ServiceID,
		&i.Recording.EventID,
		&i.Recording.Name,
		&i.Recording.Description,
		&i.Recording.StartAt,
		&i.Recording.EndAt,
		&i.Recording.State,
		&i.Recording.FailureReason,
		&i.Recording.Protected,
		&i.Recording.Drops,
		&i.Recording.Errors,
		&i.Recording.Scrambled,
		&i.Recording.Gaps,
		&i.Recording.Audios,
		&i.Recording.ProgramLost,
		&i.Recording.BroadcastStartedAt,
		&i.Recording.BroadcastEndedAt,
		&i.Recording.NotBroadcast,
		&i.Recording.AiredEventID,
		&i.Recording.RecordedFrom,
		&i.Recording.RecordedUntil,
		&i.Recording.CreatedAt,
		&i.Recording.UpdatedAt,
		&i.Inserted,
	)
	return i, err
}

const tryLockRecordingJoin = `-- name: TryLockRecordingJoin :one
SELECT pg_try_advisory_lock(hashtext('kotatsu.segjoin'), hashtext($1::text)) AS locked
`

// 録画のセグメントをつなぐ間、ほかの nekonote が同じ録画をつながないよう、セッションの advisory lock を取る。取れなければ false を返す。
func (q *Queries) TryLockRecordingJoin(ctx context.Context, recordingID string) (bool, error) {
	row := q.db.QueryRow(ctx, tryLockRecordingJoin, recordingID)
	var locked bool
	err := row.Scan(&locked)
	return locked, err
}

const unlockRecordingJoin = `-- name: UnlockRecordingJoin :one
SELECT pg_advisory_unlock(hashtext('kotatsu.segjoin'), hashtext($1::text)) AS unlocked
`

func (q *Queries) UnlockRecordingJoin(ctx context.Context, recordingID string) (bool, error) {
	row := q.db.QueryRow(ctx, unlockRecordingJoin, recordingID)
	var unlocked bool
	err := row.Scan(&unlocked)
	return unlocked, err
}

const upsertRecordingImage = `-- name: UpsertRecordingImage :exec
INSERT INTO recording_files (id, recording_id, kind, pool_id, path, size, started_at, ended_at, created_at)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $8)
ON CONFLICT (pool_id, path) DO UPDATE SET size = EXCLUDED.size, ended_at = EXCLUDED.ended_at
WHERE recording_files.recording_id = EXCLUDED.recording_id AND recording_files.kind = EXCLUDED.kind
`

type UpsertRecordingImageParams struct {
	ID          uuid.UUID
	RecordingID uuid.UUID
	Kind        string
	PoolID      string
	Path        string
	Size        int64
	StartedAt   time.Time
	Now         *time.Time
}

// 録画の代表画像かプレビュー画像を記録する。作り直したときは、同じパスの行を書き換える。
func (q *Queries) UpsertRecordingImage(ctx context.Context, arg UpsertRecordingImageParams) error {
	_, err := q.db.Exec(ctx, upsertRecordingImage,
		arg.ID,
		arg.RecordingID,
		arg.Kind,
		arg.PoolID,
		arg.Path,
		arg.Size,
		arg.StartedAt,
		arg.Now,
	)
	return err
}

